1	package darksafe
2	
3	import (
4		"errors"
5		"fmt"
6		"strings"
7		"unicode/utf16"
8		"unicode/utf8"
9	)
10	
11	// This file holds the strict text check shared by every JSON string in a
12	// release configuration: member names and string values alike, in known
13	// fields and in unknown extra fields, however deeply nested.
14	//
15	// Go's encoding/json silently rewrites two kinds of corrupt text to the
16	// replacement character "�" (U+FFFD): invalid UTF-8 bytes inside a string,
17	// and \uXXXX escapes naming an unpaired surrogate (a high surrogate not
18	// immediately followed by a low-surrogate escape, or a low surrogate with no
19	// preceding high surrogate). Decoding through encoding/json alone would
20	// therefore turn two different original documents into the same cluster ID
21	// or tag value. This check rejects such documents before any decoded string
22	// is compared, so the rewrite can never feed identity comparison, label
23	// matching, or fault-domain batching.
24	//
25	// Legal text is untouched: valid UTF-8 (including a literally written "�",
26	// which is a legal character), \uXXXX escapes for BMP characters, and
27	// high+low surrogate pairs for non-BMP characters all decode to their
28	// intended strings. A backslash-escaped "D800" is ordinary text, not an
29	// escape sequence, and is accepted as such.
30	//
31	// The scanner only recognizes text problems. Anything structurally
32	// unexpected makes it stop (errUndecided) and defer to the encoding/json
33	// walks that follow, which report the JSON format error with the established
34	// wording — so malformed documents keep their existing error messages.
35	
36	// invalidUTF8Error reports a JSON string or member name containing bytes
37	// that are not valid UTF-8. For a member name, path points at the object
38	// owning the name; for a value, at the field or array item holding it.
39	type invalidUTF8Error struct {
40		path  string
41		isKey bool
42	}
43	
44	func (e *invalidUTF8Error) Error() string {
45		if e.isKey {
46			return fmt.Sprintf("JSON 成员名包含无效 UTF-8 字节: 所属对象位置 %s", e.path)
47		}
48		return fmt.Sprintf("JSON 字符串包含无效 UTF-8 字节: 位置 %s", e.path)
49	}
50	
51	// unpairedSurrogateError reports a \uXXXX escape naming one half of a
52	// surrogate pair without its mate: a high surrogate not immediately followed
53	// by a low-surrogate escape, or a low surrogate appearing on its own.
54	// escape is the offending escape spelling (e.g. `D800`); path and isKey
55	// locate it exactly as for invalidUTF8Error.
56	type unpairedSurrogateError struct {
57		escape string
58		path   string
59		isKey  bool
60	}
61	
62	func (e *unpairedSurrogateError) Error() string {
63		if e.isKey {
64			return fmt.Sprintf("JSON 成员名包含未配对的 Unicode 转义 %s: 所属对象位置 %s", e.escape, e.path)
65		}
66		return fmt.Sprintf("JSON 字符串包含未配对的 Unicode 转义 %s: 位置 %s", e.escape, e.path)
67	}
68	
69	// errUndecided is the internal sentinel meaning "this document is not
70	// structurally recognizable here": the check stops and the encoding/json
71	// walks report the format error instead. It is never returned to callers.
72	var errUndecided = errors.New("darksafe: unrecognized JSON structure")
73	
74	// checkStrictText scans the raw document and rejects any string — member
75	// name or value, anywhere in the structure — containing invalid UTF-8 bytes
76	// or an unpaired-surrogate \uXXXX escape. It runs before duplicate-member
77	// detection and business validation, so no rewritten string can be compared
78	// or planned with. A document it cannot structurally follow is left to the
79	// later encoding/json walks, which report the format error.
80	func checkStrictText(data []byte) error {
81		s := &strictTextScanner{data: data}
82		if err := s.value("$"); err != nil && !errors.Is(err, errUndecided) {
83			return err
84		}
85		return nil
86	}
87	
88	// strictTextScanner is a recursive-descent reader over the raw document
89	// bytes. Unlike the token walks in plan.go it sees the text before any
90	// decoding, so corrupt bytes and escapes are still visible. Its path strings
91	// follow the same JSONPath-style convention as duplicateMemberError.
92	type strictTextScanner struct {
93		data []byte
94		pos  int
95	}
96	
97	func (s *strictTextScanner) skipSpace() {
98		for s.pos < len(s.data) {
99			switch s.data[s.pos] {
100			case ' ', '\t', '\n', '\r':
101				s.pos++
102			default:
103				return
104			}
105		}
106	}
107	
108	// value reads one complete JSON value at the current position.
109	func (s *strictTextScanner) value(path string) error {
110		s.skipSpace()
111		if s.pos >= len(s.data) {
112			return errUndecided
113		}
114		switch c := s.data[s.pos]; {
115		case c == '{':
116			return s.object(path)
117		case c == '[':
118			return s.array(path)
119		case c == '"':
120			_, err := s.jsonString(path, false)
121			return err
122		case c == 't':
123			return s.literal("true")
124		case c == 'f':
125			return s.literal("false")
126		case c == 'n':
127			return s.literal("null")
128		case c == '-' || ('0' <= c && c <= '9'):
129			// Numbers carry no text; skip their characters loosely and let the
130			// decoder judge whether the number itself is well-formed.
131			s.number()
132			return nil
133		default:
134			return errUndecided
135		}
136	}
137	
138	func (s *strictTextScanner) object(path string) error {
139		s.pos++ // consume '{'
140		s.skipSpace()
141		if s.pos < len(s.data) && s.data[s.pos] == '}' {
142			s.pos++
143			return nil
144		}
145		for {
146			s.skipSpace()
147			if s.pos >= len(s.data) || s.data[s.pos] != '"' {
148				return errUndecided
149			}
150			key, err := s.jsonString(path, true)
151			if err != nil {
152				return err
153			}
154			s.skipSpace()
155			if s.pos >= len(s.data) || s.data[s.pos] != ':' {
156				return errUndecided
157			}
158			s.pos++
159			if err := s.value(joinMemberPath(path, key)); err != nil {
160				return err
161			}
162			s.skipSpace()
163			if s.pos >= len(s.data) {
164				return errUndecided
165			}
166			switch s.data[s.pos] {
167			case ',':
168				s.pos++
169			case '}':
170				s.pos++
171				return nil
172			default:
173				return errUndecided
174			}
175		}
176	}
177	
178	func (s *strictTextScanner) array(path string) error {
179		s.pos++ // consume '['
180		s.skipSpace()
181		if s.pos < len(s.data) && s.data[s.pos] == ']' {
182			s.pos++
183			return nil
184		}
185		for i := 0; ; i++ {
186			if err := s.value(fmt.Sprintf("%s[%d]", path, i)); err != nil {
187				return err
188			}
189			s.skipSpace()
190			if s.pos >= len(s.data) {
191				return errUndecided
192			}
193			switch s.data[s.pos] {
194			case ',':
195				s.pos++
196			case ']':
197				s.pos++
198				return nil
199			default:
200				return errUndecided
201			}
202		}
203	}
204	
205	func (s *strictTextScanner) literal(word string) error {
206		if len(s.data)-s.pos < len(word) || string(s.data[s.pos:s.pos+len(word)]) != word {
207			return errUndecided
208		}
209		s.pos += len(word)
210		return nil
211	}
212	
213	func (s *strictTextScanner) number() {
214		for s.pos < len(s.data) {
215			switch c := s.data[s.pos]; {
216			case c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || ('0' <= c && c <= '9'):
217				s.pos++
218			default:
219				return
220			}
221		}
222	}
223	
224	// jsonString reads one string literal whose opening quote is at s.pos,
225	// validating every byte and escape, and returns the decoded contents. The
226	// decoded form is needed for member names so that object paths are built
227	// from the same decoded names the duplicate check compares.
228	func (s *strictTextScanner) jsonString(path string, isKey bool) (string, error) {
229		s.pos++ // consume the opening quote
230		rawStart := s.pos
231		var sb strings.Builder
232		decoded := false // whether sb holds the decoded prefix
233		flush := func(upto int) {
234			if !decoded {
235				sb.Write(s.data[rawStart:upto])
236				decoded = true
237			}
238		}
239		for {
240			if s.pos >= len(s.data) {
241				return "", errUndecided // unterminated: the decoder reports it
242			}
243			c := s.data[s.pos]
244			switch {
245			case c == '"':
246				s.pos++
247				if !decoded {
248					return string(s.data[rawStart : s.pos-1]), nil
249				}
250				return sb.String(), nil
251			case c == '\\':
252				flush(s.pos)
253				s.pos++
254				if err := s.escape(&sb, path, isKey); err != nil {
255					return "", err
256				}
257			case c < 0x20:
258				// A raw control character is a JSON format error; leave the
259				// report to the decoder.
260				return "", errUndecided
261			case c < utf8.RuneSelf:
262				if decoded {
263					sb.WriteByte(c)
264				}
265				s.pos++
266			default:
267				r, size := utf8.DecodeRune(s.data[s.pos:])
268				// RuneError with size 1 means the bytes are not valid UTF-8; a
269				// literally written "�" decodes with size 3 and is legal text.
270				if r == utf8.RuneError && size == 1 {
271					return "", &invalidUTF8Error{path: path, isKey: isKey}
272				}
273				if decoded {
274					sb.Write(s.data[s.pos : s.pos+size])
275				}
276				s.pos += size
277			}
278		}
279	}
280	
281	// escape consumes one escape sequence (the backslash is already consumed)
282	// and writes the decoded character to sb.
283	func (s *strictTextScanner) escape(sb *strings.Builder, path string, isKey bool) error {
284		if s.pos >= len(s.data) {
285			return errUndecided
286		}
287		e := s.data[s.pos]
288		s.pos++
289		switch e {
290		case '"', '\\', '/':
291			sb.WriteByte(e)
292		case 'b':
293			sb.WriteByte('\b')
294		case 'f':
295			sb.WriteByte('\f')
296		case 'n':
297			sb.WriteByte('\n')
298		case 'r':
299			sb.WriteByte('\r')
300		case 't':
301			sb.WriteByte('\t')
302		case 'u':
303			r, err := s.unicodeEscape(path, isKey)
304			if err != nil {
305				return err
306			}
307			sb.WriteRune(r)
308		default:
309			// An unknown escape is a JSON format error, reported by the decoder.
310			return errUndecided
311		}
312		return nil
313	}
314	
315	// unicodeEscape reads the four hex digits of a \uXXXX escape (the "\u" is
316	// already consumed) and, for a high surrogate, the low-surrogate escape that
317	// must immediately follow. It returns the decoded rune: the BMP character
318	// itself, or the non-BMP character a surrogate pair stands for.
319	func (s *strictTextScanner) unicodeEscape(path string, isKey bool) (rune, error) {
320		r, ok := s.hex4()
321		if !ok {
322			return 0, errUndecided // malformed hex: the decoder reports it
323		}
324		if !utf16.IsSurrogate(r) {
325			return r, nil
326		}
327		unpaired := &unpairedSurrogateError{
328			escape: fmt.Sprintf(`\u%04X`, uint16(r)),
329			path:   path,
330			isKey:  isKey,
331		}
332		if r >= 0xDC00 {
333			// A low surrogate with no preceding high surrogate.
334			return 0, unpaired
335		}
336		// A high surrogate must be immediately followed by a `\uDC00`–`\uDFFF`
337		// escape; anything else — end of string, a plain character, another
338		// escape kind, or a non-low-surrogate \uXXXX — leaves it unpaired.
339		if s.pos+1 < len(s.data) && s.data[s.pos] == '\\' && s.data[s.pos+1] == 'u' {
340			s.pos += 2
341			lo, ok := s.hex4()
342			if !ok {
343				return 0, errUndecided // malformed hex: the decoder reports it
344			}
345			if lo >= 0xDC00 && lo <= 0xDFFF {
346				return utf16.DecodeRune(r, lo), nil
347			}
348		}
349		return 0, unpaired
350	}
351	
352	// hex4 reads exactly four hexadecimal digits. It reports false — consuming
353	// nothing — when they are absent or not hex, leaving the format error to the
354	// decoder.
355	func (s *strictTextScanner) hex4() (rune, bool) {
356		if s.pos+4 > len(s.data) {
357			return 0, false
358		}
359		var v rune
360		for i := 0; i < 4; i++ {
361			c := s.data[s.pos+i]
362			var d byte
363			switch {
364			case '0' <= c && c <= '9':
365				d = c - '0'
366			case 'a' <= c && c <= 'f':
367				d = c - 'a' + 10
368			case 'A' <= c && c <= 'F':
369				d = c - 'A' + 10
370			default:
371				return 0, false
372			}
373			v = v*16 + rune(d)
374		}
375		s.pos += 4
376		return v, true
377	}
