1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
40		// fault domain; each batch then contains at most one cluster per domain.
41		SpreadBy string
42	}
43	
44	// AppInfo identifies the application being released.
45	type AppInfo struct {
46		Name     string `json:"name"`
47		Revision string `json:"revision"`
48		Image    string `json:"image"`
49	}
50	
51	// Batch is a sequentially numbered group of cluster IDs.
52	type Batch struct {
53		Index    int      `json:"index"`
54		Clusters []string `json:"clusters"`
55	}
56	
57	// ExcludedCluster explains why a cluster is not in the plan.
58	type ExcludedCluster struct {
59		ID     string `json:"id"`
60		Reason string `json:"reason"`
61	}
62	
63	// ReleasePlan is the deterministic offline release plan.
64	type ReleasePlan struct {
65		App      AppInfo           `json:"app"`
66		Batches  []Batch           `json:"batches"`
67		Excluded []ExcludedCluster `json:"excluded"`
68	}
69	
70	// ParseReleaseInput reads a release plan document and validates its fields.
71	// Every string in the document — member names and values, in known fields
72	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
73	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
74	// decoded string can be silently rewritten to "�" and compared. Every JSON
75	// object in the document — including unknown fields and their nested
76	// objects — must then have distinct member names; a name appearing twice
77	// (even with the same value, or via equivalent Unicode escapes) is rejected
78	// before any business validation runs.
79	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
80		if err := checkStrictText(data); err != nil {
81			return ReleasePlanInput{}, err
82		}
83		if err := checkDuplicateMembers(data); err != nil {
84			return ReleasePlanInput{}, err
85		}
86		dec := json.NewDecoder(bytes.NewReader(data))
87		dec.UseNumber()
88		var doc map[string]any
89		if err := dec.Decode(&doc); err != nil {
90			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
91		}
92		if dec.More() {
93			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
94		}
95		return buildReleaseInput(doc)
96	}
97	
98	// duplicateMemberError reports a JSON object whose member name appears more
99	// than once. Path is a JSONPath-style location that points at the object
100	// owning the duplicate (the duplicate member name itself is reported
101	// separately in field): "$" for the document root, "$.clusters[1]" for a
102	// cluster, "$.clusters[0].tags" for a tag object,
103	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
104	// objects nested inside unknown fields. A member name that is not a plain
105	// identifier is wrapped in brackets around a JSON string, so that characters
106	// in the name can never be read as hierarchy or an array index: a top-level
107	// member "meta.info" is at $["meta.info"] (distinct from the nested object
108	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
109	// that are empty or contain quotes, backslashes or control characters are
110	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
111	type duplicateMemberError struct {
112		field string
113		path  string
114	}
115	
116	func (e *duplicateMemberError) Error() string {
117		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
118	}
119	
120	// checkDuplicateMembers walks every JSON object in data and rejects objects
121	// with duplicate member names. Names are compared after JSON decoding, so
122	// "env" and "env" are the same name while "env" and "ENV", or
123	// " env" and "env", are different. The first duplicate encountered in file
124	// order is reported: the walk is depth-first in document order, so the
125	// second occurrence that appears earliest wins, regardless of value type.
126	func checkDuplicateMembers(data []byte) error {
127		dec := json.NewDecoder(bytes.NewReader(data))
128		// Numbers are only walked past, never interpreted: UseNumber keeps legal
129		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
130		// unmarshal-overflow error here. Whether a number is acceptable for a given
131		// field is decided later by business validation.
132		dec.UseNumber()
133		if err := walkJSONValue(dec, "$"); err != nil {
134			return err
135		}
136		if _, err := dec.Token(); err != io.EOF {
137			if err == nil {
138				return errors.New("JSON 格式错误: 文档包含多余内容")
139			}
140			return fmt.Errorf("JSON 格式错误: %w", err)
141		}
142		return nil
143	}
144	
145	// walkJSONValue reads one complete JSON value whose first token has not been
146	// consumed yet.
147	func walkJSONValue(dec *json.Decoder, path string) error {
148		tok, err := dec.Token()
149		if err != nil {
150			if err == io.EOF {
151				return errors.New("JSON 格式错误: 文档为空")
152			}
153			return fmt.Errorf("JSON 格式错误: %w", err)
154		}
155		return walkJSONValueToken(dec, path, tok)
156	}
157	
158	// walkJSONValueToken reads the remainder of a value given its first token.
159	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
160		if d, ok := tok.(json.Delim); ok {
161			switch d {
162			case '{':
163				return walkJSONObject(dec, path)
164			case '[':
165				return walkJSONArray(dec, path)
166			default:
167				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
168			}
169		}
170		return nil // scalar value (string, number, bool, null)
171	}
172	
173	func walkJSONObject(dec *json.Decoder, path string) error {
174		seen := make(map[string]struct{})
175		for {
176			tok, err := dec.Token()
177			if err != nil {
178				if err == io.EOF {
179					return errors.New("JSON 格式错误: 对象未闭合")
180				}
181				return fmt.Errorf("JSON 格式错误: %w", err)
182			}
183			if d, ok := tok.(json.Delim); ok {
184				if d == '}' {
185					return nil
186				}
187				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
188			}
189			key, ok := tok.(string)
190			if !ok {
191				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
192			}
193			if _, dup := seen[key]; dup {
194				return &duplicateMemberError{field: key, path: path}
195			}
196			seen[key] = struct{}{}
197			vtok, err := dec.Token()
198			if err != nil {
199				if err == io.EOF {
200					return errors.New("JSON 格式错误: 缺少成员值")
201				}
202				return fmt.Errorf("JSON 格式错误: %w", err)
203			}
204			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok); err != nil {
205				return err
206			}
207		}
208	}
209	
210	// isSimpleMemberName reports whether key may be written with dot notation:
211	// it must start with an ASCII letter or underscore and contain only ASCII
212	// letters, digits, and underscores afterward.
213	func isSimpleMemberName(key string) bool {
214		if key == "" {
215			return false
216		}
217		for i, r := range key {
218			switch {
219			case r == '_' || ('a' <= r && r <= 'z') || ('A' <= r && r <= 'Z'):
220			case i > 0 && ('0' <= r && r <= '9'):
221			default:
222				return false
223			}
224		}
225		return true
226	}
227	
228	// joinMemberPath extends an object location with one member name. Simple
229	// identifier names keep the existing dot spelling ("$.clusters[0].tags");
230	// every other name is rendered as brackets around a JSON-encoded string, so
231	// the text decodes back to exactly the real member name and none of its
232	// characters can be mistaken for a path separator or array index.
233	func joinMemberPath(path, key string) string {
234		if isSimpleMemberName(key) {
235			return path + "." + key
236		}
237		return path + "[" + jsonEncodePathString(key) + "]"
238	}
239	
240	// jsonEncodePathString renders key as a legal JSON string (including the
241	// surrounding quotes); decoding the result restores key exactly, including
242	// empty names and names containing quotes, backslashes, newlines or other
243	// control characters.
244	func jsonEncodePathString(key string) string {
245		bs, err := json.Marshal(key)
246		if err != nil {
247			// json.Marshal cannot fail for a Go string.
248			panic(fmt.Sprintf("json.Marshal(%q): %v", key, err))
249		}
250		return string(bs)
251	}
252	
253	func walkJSONArray(dec *json.Decoder, path string) error {
254		for i := 0; ; i++ {
255			tok, err := dec.Token()
256			if err != nil {
257				if err == io.EOF {
258					return errors.New("JSON 格式错误: 数组未闭合")
259				}
260				return fmt.Errorf("JSON 格式错误: %w", err)
261			}
262			if d, ok := tok.(json.Delim); ok && d == ']' {
263				return nil
264			}
265			if err := walkJSONValueToken(dec, fmt.Sprintf("%s[%d]", path, i), tok); err != nil {
266				return err
267			}
268		}
269	}
270	
271	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
272		app, err := requiredString(doc, "app")
273		if err != nil {
274			return ReleasePlanInput{}, err
275		}
276		revision, err := requiredString(doc, "revision")
277		if err != nil {
278			return ReleasePlanInput{}, err
279		}
280		image, err := requiredString(doc, "image")
281		if err != nil {
282			return ReleasePlanInput{}, err
283		}
284		batchSize, err := positiveInt(doc, "batchSize")
285		if err != nil {
286			return ReleasePlanInput{}, err
287		}
288		spreadBy, err := optionalSpreadBy(doc)
289		if err != nil {
290			return ReleasePlanInput{}, err
291		}
292		clusters, err := parseClusters(doc["clusters"])
293		if err != nil {
294			return ReleasePlanInput{}, err
295		}
296		include, err := parseConditions(doc["include"], "include")
297		if err != nil {
298			return ReleasePlanInput{}, err
299		}
300		exclude, err := parseConditions(doc["exclude"], "exclude")
301		if err != nil {
302			return ReleasePlanInput{}, err
303		}
304	
305		return ReleasePlanInput{
306			App:       app,
307			Revision:  revision,
308			Image:     image,
309			BatchSize: batchSize,
310			Clusters:  clusters,
311			Include:   include,
312			Exclude:   exclude,
313			SpreadBy:  spreadBy,
314		}, nil
315	}
316	
317	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
318	// string disables fault-domain spreading; a non-string value or a string of
319	// only whitespace is rejected. The tag key is used exactly as written.
320	func optionalSpreadBy(doc map[string]any) (string, error) {
321		v, ok := doc["spreadBy"]
322		if !ok {
323			return "", nil
324		}
325		s, ok := v.(string)
326		if !ok {
327			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
328		}
329		if err := checkSpreadBy(s); err != nil {
330			return "", err
331		}
332		return s, nil
333	}
334	
335	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
336	// tag key: a string of only whitespace can never match a valid tag key.
337	func checkSpreadBy(s string) error {
338		if s != "" && strings.TrimSpace(s) == "" {
339			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
340		}
341		return nil
342	}
343	
344	// ValidateReleaseInput checks that a release configuration is well-formed:
345	// app/revision/image are non-empty, batchSize is a positive integer, spreadBy
346	// is empty or a usable tag key (not whitespace-only), cluster
347	// IDs are unique across every candidate (including disabled and filtered-out
348	// clusters), and tag/condition keys are non-empty. Errors name the field and
349	// the position in its list; within a cluster the ID is checked before its
350	// tags, and tag keys are examined in ascending order so repeated calls report
351	// the same error. The input is never mutated. MakeReleasePlan calls this
352	// automatically; library callers may use it to validate without planning.
353	func ValidateReleaseInput(in ReleasePlanInput) error {
354		if strings.TrimSpace(in.App) == "" {
355			return errors.New(`字段 "app" 不能为空或只含空白`)
356		}
357		if strings.TrimSpace(in.Revision) == "" {
358			return errors.New(`字段 "revision" 不能为空或只含空白`)
359		}
360		if strings.TrimSpace(in.Image) == "" {
361			return errors.New(`字段 "image" 不能为空或只含空白`)
362		}
363		if in.BatchSize <= 0 {
364			return errors.New(`字段 "batchSize" 必须是正整数`)
365		}
366		if err := checkSpreadBy(in.SpreadBy); err != nil {
367			return err
368		}
369		ids := newClusterIDSet(len(in.Clusters))
370		for i, c := range in.Clusters {
371			if err := ids.check(i, c.ID); err != nil {
372				return err
373			}
374			if err := validateTagKeys(i, c.Tags); err != nil {
375				return err
376			}
377		}
378		if err := validateConditionKeys("include", in.Include); err != nil {
379			return err
380		}
381		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
382			return err
383		}
384		return nil
385	}
386	
387	// validateTagKeys applies the shared label-key rule to one cluster's tags,
388	// reporting the cluster's position in the candidate list.
389	func validateTagKeys(clusterIndex int, tags map[string]string) error {
390		if hasEmptyLabelKey(tags) {
391			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
392		}
393		return nil
394	}
395	
396	// validateConditionKeys applies the shared condition rules to every condition
397	// in original order, so the first invalid condition is reported.
398	func validateConditionKeys(field string, conds []LabelCondition) error {
399		for i, cond := range conds {
400			if err := validateCondition(field, i, cond); err != nil {
401				return err
402			}
403		}
404		return nil
405	}
406	
407	func requiredString(doc map[string]any, field string) (string, error) {
408		v, ok := doc[field]
409		if !ok {
410			return "", fmt.Errorf("缺少必需字段 %q", field)
411		}
412		s, ok := v.(string)
413		if !ok {
414			return "", fmt.Errorf("字段 %q 必须是字符串", field)
415		}
416		if strings.TrimSpace(s) == "" {
417			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
418		}
419		return s, nil
420	}
421	
422	func positiveInt(doc map[string]any, field string) (int, error) {
423		v, ok := doc[field]
424		if !ok {
425			return 0, fmt.Errorf("缺少必需字段 %q", field)
426		}
427		n, ok := v.(json.Number)
428		if !ok {
429			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
430		}
431		i, err := n.Int64()
432		if err != nil || i <= 0 {
433			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
434		}
435		return int(i), nil
436	}
437	
438	func parseClusters(v any) ([]Cluster, error) {
439		if v == nil {
440			return nil, errors.New("缺少必需字段 \"clusters\"")
441		}
442		raw, ok := v.([]any)
443		if !ok {
444			return nil, errors.New("字段 \"clusters\" 必须是数组")
445		}
446		clusters := make([]Cluster, 0, len(raw))
447		ids := newClusterIDSet(len(raw))
448		for i, item := range raw {
449			obj, ok := item.(map[string]any)
450			if !ok {
451				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
452			}
453			id, err := clusterIDFromJSON(obj, i, ids)
454			if err != nil {
455				return nil, err
456			}
457	
458			disabled := false
459			if dv, present := obj["disabled"]; present {
460				b, ok := dv.(bool)
461				if !ok {
462					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
463				}
464				disabled = b
465			}
466	
467			tags := map[string]string{}
468			if tv, present := obj["tags"]; present {
469				tm, ok := tv.(map[string]any)
470				if !ok {
471					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
472				}
473				tags, err = labelsFromJSON(tm,
474					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
475					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
476				)
477				if err != nil {
478					return nil, err
479				}
480			}
481	
482			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
483		}
484		return clusters, nil
485	}
486	
487	// clusterIDFromJSON reads the "id" member of one candidate object and applies
488	// the shared cluster-identity rule. A missing member or a non-string value is
489	// a JSON decoding problem with its own reason; an empty or duplicate ID is
490	// reported by the shared rule exactly as for a directly constructed config.
491	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
492		v, ok := obj["id"]
493		if !ok {
494			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
495		}
496		id, ok := v.(string)
497		if !ok {
498			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
499		}
500		if err := ids.check(index, id); err != nil {
501			return "", err
502		}
503		return id, nil
504	}
505	
506	func parseConditions(v any, field string) ([]LabelCondition, error) {
507		if v == nil {
508			return []LabelCondition{}, nil
509		}
510		raw, ok := v.([]any)
511		if !ok {
512			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
513		}
514		conds := make([]LabelCondition, 0, len(raw))
515		for i, item := range raw {
516			obj, ok := item.(map[string]any)
517			if !ok {
518				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
519			}
520			cond, err := labelsFromJSON(obj,
521				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
522				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
523			)
524			if err != nil {
525				return nil, err
526			}
527			if err := validateCondition(field, i, cond); err != nil {
528				return nil, err
529			}
530			conds = append(conds, cond)
531		}
532		return conds, nil
533	}
534	
535	// MakeReleasePlan selects available clusters, orders them by ID, and splits
536	// them into batches. When SpreadBy names a tag, each batch holds at most one
537	// cluster per value of that tag (its fault domain) and every selected cluster
538	// must carry the tag. It validates the input first and never mutates it.
539	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
540		if err := ValidateReleaseInput(in); err != nil {
541			return ReleasePlan{}, err
542		}
543		if len(in.Clusters) == 0 {
544			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
545		}
546	
547		selected := []string{}
548		excluded := []ExcludedCluster{}
549		for _, c := range in.Clusters {
550			switch {
551			case c.Disabled:
552				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
553			case matchesAny(c.Tags, in.Exclude):
554				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
555			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
556				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
557			default:
558				selected = append(selected, c.ID)
559			}
560		}
561	
562		sort.Strings(selected)
563		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
564	
565		if len(selected) == 0 {
566			var b strings.Builder
567			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
568			for _, e := range excluded {
569				b.WriteString("\n  ")
570				b.WriteString(e.ID)
571				b.WriteString("：")
572				b.WriteString(e.Reason)
573			}
574			return ReleasePlan{}, errors.New(b.String())
575		}
576	
577		var batches []Batch
578		if in.SpreadBy == "" {
579			batches = chunkBatches(selected, in.BatchSize)
580		} else {
581			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
582			if err != nil {
583				return ReleasePlan{}, err
584			}
585			batches = spreadBatches(selected, domains, in.BatchSize)
586		}
587	
588		return ReleasePlan{
589			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
590			Batches:  batches,
591			Excluded: excluded,
592		}, nil
593	}
594	
595	// chunkBatches splits the ascending IDs into batches of at most batchSize.
596	func chunkBatches(selected []string, batchSize int) []Batch {
597		batches := []Batch{}
598		for i := 0; i < len(selected); i += batchSize {
599			end := i + batchSize
600			if end > len(selected) {
601				end = len(selected)
602			}
603			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
604		}
605		return batches
606	}
607	
608	// faultDomains maps every selected cluster ID to the exact value of its
609	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
610	// selected is ascending, so the smallest such ID is reported. An empty
611	// string tag value is a valid fault domain, distinct from a missing tag.
612	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
613		tagsByID := make(map[string]map[string]string, len(clusters))
614		for _, c := range clusters {
615			tagsByID[c.ID] = c.Tags
616		}
617		domains := make(map[string]string, len(selected))
618		for _, id := range selected {
619			v, ok := tagsByID[id][spreadBy]
620			if !ok {
621				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
622			}
623			domains[id] = v
624		}
625		return domains, nil
626	}
627	
628	// spreadBatches packs the ascending IDs into batches of at most batchSize
629	// with at most one cluster per fault domain in each batch. Each batch takes
630	// the smallest still-unscheduled IDs whose domains do not conflict with the
631	// batch; conflicting clusters are deferred to later batches, so a batch may
632	// be short only when no non-conflicting cluster remains. Every ID appears in
633	// exactly one batch and IDs stay ascending within a batch.
634	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
635		remaining := append([]string(nil), selected...)
636		batches := []Batch{}
637		for len(remaining) > 0 {
638			// The map never holds more entries than there are remaining clusters,
639			// so size it by them — never by batchSize, which is only an upper
640			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
641			used := make(map[string]struct{}, min(batchSize, len(remaining)))
642			batch := []string{}
643			deferred := []string{}
644			for _, id := range remaining {
645				d := domains[id]
646				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
647					used[d] = struct{}{}
648					batch = append(batch, id)
649				} else {
650					deferred = append(deferred, id)
651				}
652			}
653			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
654			remaining = deferred
655		}
656		return batches
657	}
658	
659	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
660		for _, cond := range conditions {
661			if matchesAll(tags, cond) {
662				return true
663			}
664		}
665		return false
666	}
667	
668	func matchesAll(tags map[string]string, cond LabelCondition) bool {
669		for k, v := range cond {
670			tv, ok := tags[k]
671			if !ok || tv != v {
672				return false
673			}
674		}
675		return true
676	}
677

