	"testing"
)

// Differential harness (not part of the product test suite): prints the
// ParseReleaseInput verdict for a corpus of documents so the old and new
// implementations can be diffed byte for byte.
func TestCorpusDump(t *testing.T) {
	bad := "\xff"
	corpus := []string{
		// valid configs
		`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]}`,
		`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[{"id":"c1","tags":{"env":"prod"}}],"include":[{"env":"prod"}],"spreadBy":"env"}`,
		`{"app":"支付服务","revision":"版本","image":"镜像","batchSize":2,"clusters":[{"id":"集群-一"}],"meta":{"x":1},"zone[0]":{"y":2},"":"empty"}`,
		// duplicates
		`{"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]}`,
		`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[{"id":"x","tags":{"env":1,"env":2}}]}`,
		`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[{"id":"x","tags":{"env":1,"env":2}}]}`,
		`{"app":"a","revision":"r","image":"i","batchSize":1,"meta.info":{"x":1,"x":2},"clusters":[]}`,
		// corrupt text
		`{"app":"a` + bad + `","revision":"r","image":"i","batchSize":1,"clusters":[]}`,
		`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[],"me` + bad + `ta":1}`,
